"OLAYLAR_ORTACAG_ORTADOGU:1285-01-01:0":{"b": ["カラーウーンは聖ヨハネ騎士団のマルカブ（Margat）城を奪ってこの十字軍勢力を排除した。トリポリ伯国の近傍にあった最後の大きな十字軍の要塞が陥落した（684/1285）。", "722b884f"], "d": ["カラーウーンは聖ヨハネ騎士団のマルカブ（Margat）城を奪ってこの十字軍勢力を排除した。トリポリ伯国の近傍にあった最後の大きな十字軍の要塞が陥落した（684/1285）。", "722b884f"]},
"OLAYLAR_ORTACAG_ORTADOGU:1287-01-01:0":{"b": ["伯ボエモン7世が死去した。妹のルシアと、ジェノヴァ人に支援された都市コミューンとの間の相続争いが伯国を弱体化させ、カラーウーンに好機を与えた。", "e68819ba"], "d": ["伯ボエモン7世が死去した。妹のルシアと、ジェノヴァ人に支援された都市コミューンとの間の相続争いが伯国を弱体化させ、カラーウーンに好機を与えた。", "e68819ba"]},
"OLAYLAR_ORTACAG_ORTADOGU:1289-04-26:0":{"b": ["カラーウーンがトリポリを征服した：トリポリ伯国は終わった", "2c912cc3"], "d": ["カラーウーンがトリポリを征服した：トリポリ伯国は終わった", "2c912cc3"]},
"OLAYLAR_ORTACAG_ORTADOGU:1291-07-01:0":{"b": ["サイダ（シドン）がマムルーク朝の手に渡った（テンプル騎士団は撤退した）", "2339a488"], "d": ["アッコの陥落（690/1291）を受けてそこを離れたテンプル騎士団はサイダに避難した。都市はヒジュラ暦690年ラジャブ月／1291年7月にマムルーク朝の手に渡り、城壁は破壊させられた。", "4c9103e0"]},
"OLAYLAR_ORTACAG_ORTADOGU:1291-07-14:0":{"b": ["マムルーク朝がティルスを奪った：十字軍の沿岸国家（エルサレム王国）は終わった", "f52aa213"], "d": ["マムルーク朝がティルスを奪った：十字軍の沿岸国家（エルサレム王国）は終わった", "f52aa213"]},
"OLAYLAR_ORTACAG_ORTADOGU:1310-10-03:0":{"b": ["歴史家アブー・アルフィダーがマムルーク朝のスルタンによりハマーの代官に任じられた（ヒジュラ暦710年ジュマーダー・アル=ウーラー月8日）。", "8dbf5f8f"], "d": ["歴史家アブー・アルフィダーがマムルーク朝のスルタンによりハマーの代官に任じられた（ヒジュラ暦710年ジュマーダー・アル=ウーラー月8日）。", "8dbf5f8f"]},
"OLAYLAR_ORTACAG_ORTADOGU:1312-08-30:0":{"b": ["アブー・アルフィダーが「アル=マリク・アッサーリフ」の称号でハマーの君主となった（ヒジュラ暦712年ラビー・アッサーニー月25日）。", "e03a1512"], "d": ["アブー・アルフィダーが「アル=マリク・アッサーリフ」の称号でハマーの君主となった（ヒジュラ暦712年ラビー・アッサーニー月25日）。", "e03a1512"]},
